"""Preview and, only with --confirm, import PVDAQ 35 through formal FILE Adapter."""
import argparse,csv,json
from pathlib import Path
import httpx
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'real_public_datasets'/'pvdaq_system35';NORMAL=BASE/'normalized';API='http://127.0.0.1:8000'
def checked(r):
 if not r.is_success:raise RuntimeError(f'{r.request.method} {r.request.url}: {r.status_code} {r.text[:1000]}')
 return r.json()
def rows(name):return list(csv.DictReader((NORMAL/name).open(encoding='utf-8-sig')))
def main(confirm=False):
 metrics=rows('pv_metrics.csv');preview={'status':'PREVIEW_ONLY' if not confirm else 'CONFIRMED','source_file':str((NORMAL/'pv_metrics.csv').resolve()),'record_count':len(metrics),'columns':list(metrics[0]),'sample':metrics[:5],'metric_counts':{m:sum(x['metric_name']==m for x in metrics) for m in sorted({x['metric_name'] for x in metrics})},'time_range':[min(x['timestamp'] for x in metrics),max(x['timestamp'] for x in metrics)],'writes_performed':False};(BASE/'preview.json').write_text(json.dumps(preview,ensure_ascii=False,indent=2),encoding='utf-8')
 if not confirm:print(json.dumps(preview,ensure_ascii=False,indent=2));return
 with httpx.Client(base_url=API,timeout=300,trust_env=False) as c:
  enterprise=next((x for x in checked(c.get('/api/enterprises')) if x['name']=='NREL PVDAQ Public Validation'),None) or checked(c.post('/api/enterprises',json={'name':'NREL PVDAQ Public Validation','region':'US-Nevada','industry':'Public PV performance validation','base_year':2010}))
  org=next((x for x in checked(c.get('/api/organizations',params={'enterprise_id':enterprise['id']})) if x.get('code')=='PVDAQ-35'),None) or checked(c.post('/api/organizations',json={'enterprise_id':enterprise['id'],'name':'PVDAQ 35 Validation Organization','level':'BUILDING_PARK','code':'PVDAQ-35','metadata_json':{'data_class':'REAL_PUBLIC','doi':'10.25984/1846021'}}))
  site=next((x for x in checked(c.get('/api/sites',params={'enterprise_id':enterprise['id']})) if x['code']=='PVDAQ-35'),None) or checked(c.post('/api/sites',json={'enterprise_id':enterprise['id'],'organization_node_id':org['id'],'code':'PVDAQ-35','name':'PV Validation Site · NREL PVDAQ 35','site_type':'OTHER','address':'Las Vegas, Nevada, United States','timezone':'America/Los_Angeles','latitude':36.1952,'longitude':-115.1582,'metadata_json':{'data_class':'REAL_PUBLIC','dataset':'NREL PVDAQ System 35','doi':'10.25984/1846021','country':'US','not_target_china_site':True}}))
  system=next((x for x in checked(c.get('/api/energy-systems',params={'site_id':site['id']})) if x['code']=='PVDAQ-35-SYSTEM'),None) or checked(c.post('/api/energy-systems',json={'site_id':site['id'],'code':'PVDAQ-35-SYSTEM','name':'PVDAQ 35 PV EnergySystem','system_type':'PV','metadata_json':{'data_class':'REAL_PUBLIC','installed_capacity_kwp':121.68}}))
  source=next((x for x in checked(c.get('/api/data-sources',params={'enterprise_id':enterprise['id']})) if x['name']=='NREL PVDAQ 35 official FILE'),None) or checked(c.post('/api/data-sources',json={'enterprise_id':enterprise['id'],'name':'NREL PVDAQ 35 official FILE','source_type':'FILE','config_json':{'path':str((NORMAL/'pv_metrics.csv').resolve()),'timezone':'UTC','source_record_id_path':'source_record_id','data_class':'REAL_PUBLIC','dataset':'NREL PVDAQ System 35','doi':'10.25984/1846021','preview_file':str((BASE/'preview.json').resolve())}}))
  existing={x['external_id']:x for x in checked(c.get('/api/devices',params={'enterprise_id':enterprise['id']}))};d=rows('devices.csv')[0];device=existing.get(d['external_id']) or checked(c.post('/api/devices',json={'enterprise_id':enterprise['id'],'data_source_id':source['id'],'external_id':d['external_id'],'name':d['name'],'device_type':'PV','longitude':float(d['longitude']),'latitude':float(d['latitude']),'metadata_json':{'data_class':'REAL_PUBLIC','installed_capacity_kwp':121.68,'module_power_w':240,'module_count':507,'inverter_capacity_kw':135,'azimuth_deg':270,'tilt_deg':None,'model_parameter_fallback':{'performance_ratio':.85,'inverter_efficiency':1,'noct_c':45,'temperature_coefficient_per_c':-.004}}}))
  before=checked(c.get(f"/api/data-sources/{source['id']}/data-quality"));sync=checked(c.post(f"/api/data-sources/{source['id']}/sync")) if before['valid_records']==0 else {'idempotent_resume':True,'inserted':before['valid_records']}
  old={x['code']:x for x in checked(c.get('/api/metering-points',params={'site_id':site['id']}))};points=[]
  for p in rows('metering_points.csv'):points.append(old.get(p['code']) or checked(c.post('/api/metering-points',json={'site_id':site['id'],'energy_system_id':system['id'],'device_id':device['id'],'data_source_id':source['id'],'code':p['code'],'name':p['name'],'metric_type':p['metric_type'],'energy_type':'PV','unit':p['unit'],'metadata_json':{'data_class':'REAL_PUBLIC','observed':True}})))
  result={'preview':preview,'enterprise':enterprise,'site':site,'energy_system':system,'data_source':source,'devices':[device],'metering_points':points,'sync':sync,'quality':checked(c.get(f"/api/data-sources/{source['id']}/data-quality"))};preview['writes_performed']=True
 (BASE/'import_result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'site_id':site['id'],'source_id':source['id'],'sync':sync,'quality':result['quality']},ensure_ascii=False,indent=2))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--confirm',action='store_true');main(p.parse_args().confirm)
